class Solution {
public:
    string entityParser(string text) {
        string result;
        result.reserve(text.size());
        int n = text.size();
        int i = 0;
        while (i < n) {
            if (text[i] == '&') {
                if (i + 6 <= n && text.compare(i, 6, "&quot;") == 0) {
                    result += '"';
                    i += 6;
                } else if (i + 6 <= n && text.compare(i, 6, "&apos;") == 0) {
                    result += '\'';
                    i += 6;
                } else if (i + 5 <= n && text.compare(i, 5, "&amp;") == 0) {
                    result += '&';
                    i += 5;
                } else if (i + 4 <= n && text.compare(i, 4, "&gt;") == 0) {
                    result += '>';
                    i += 4;
                } else if (i + 4 <= n && text.compare(i, 4, "&lt;") == 0) {
                    result += '<';
                    i += 4;
                } else if (i + 7 <= n && text.compare(i, 7, "&frasl;") == 0) {
                    result += '/';
                    i += 7;
                } else {
                    result += '&';
                    i++;
                }
            } else {
                result += text[i];
                i++;
            }
        }
        return result;
    }
};
